sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float levels;
uniform float mode;
uniform float dither;
uniform float smoothing;
uniform float saturation;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
float luma(float3 c) {
    return dot(c, float3(0.2126, 0.7152, 0.0722));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float hash21(float2 p) {
    return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
}
float3 rgb2hsv(float3 c) {
    float4 K = float4(0.0, -0.3333333, 0.6666667, -1.0);
    float4 p = mix(float4(c.b, c.g, K.w, K.z), float4(c.g, c.b, K.x, K.y), step(c.b, c.g));
    float4 q = mix(float4(p.x, p.y, p.w, c.r), float4(c.r, p.y, p.z, p.x), step(p.x, c.r));
    float d = q.x - min(q.w, q.y);
    return float3(abs(q.z + (q.w - q.y) / (6.0 * d + 0.0000001)), d / (q.x + 0.0000001), q.x);
}
float3 hsv2rgb(float3 c) {
    float3 p = abs(fract(float3(c.x) + float3(1.0, 0.6666667, 0.3333333)) * 6.0 - 3.0);
    return c.z * mix(float3(1.0), saturate(p - 1.0), c.y);
}
float3 sat3(float3 c, float s) {
    return mix(float3(dot(c, float3(0.2126, 0.7152, 0.0722))), c, s);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float n = max(levels, 2.0) - 1.0;
    float dn = (hash21(coord) - 0.5) * dither;
    float3 o = s;
    if (mode < 0.5) {
        o = floor(s * n + 0.5 + dn) / n;
    } else if (mode < 1.5) {
        float l = luma(s);
        float ql = floor(l * n + 0.5 + dn) / n;
        o = s * (ql / max(l, 0.001));
    } else {
        float3 h = rgb2hsv(s);
        h.z = floor(h.z * n + 0.5 + dn) / n;
        o = hsv2rgb(h);
    }
    o = mix(o, s, smoothing);
    o = sat3(o, saturation);
    return fin(c, float4(saturate(o) * c.a, c.a), opacity);
}
